package com.progweb.backend.seguridad;
import java.util.*;
import com.progweb.backend.respuestas.RespuestaUsuario;
import com.progweb.backend.servicios.ServicioTokens;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.web.FilterChainProxy;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.context.WebApplicationContext;
import org.springframework.security.crypto.password.PasswordEncoder;
import tools.jackson.databind.ObjectMapper;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"mensajeria.sms-habilitado=false"})
@Transactional
class AdministracionPruebas {
 @Autowired WebApplicationContext contexto;@Autowired FilterChainProxy filtro;@Autowired JdbcTemplate consultas;@Autowired ServicioTokens tokens;@Autowired PasswordEncoder codificador;@Autowired ObjectMapper json;
 MockMvc cliente;long coordinador,alumno,profesor,estudiante,tutor,departamento,carrera,periodo,sesion;String prefijo;
 final String ruta="/api/coordinacion/administracion";
 long insertar(String sql,Object... valores){consultas.update(sql,valores);return consultas.queryForObject("SELECT LAST_INSERT_ID()",Long.class);}
 long cuenta(String nombre,String rol){long id=insertar("INSERT INTO usuarios(nombre,correo,password_hash) VALUES (?,?,?)",nombre,prefijo+nombre+"@example.invalid",codificador.encode("PruebaAdmin!2026"));consultas.update("INSERT INTO usuario_roles(usuario_id,rol_id) SELECT ?,id FROM roles WHERE codigo=?",id,rol);return id;}
 String token(long id,String rol){return "Bearer "+tokens.crearToken(new RespuestaUsuario(id,"Prueba","prueba@example.invalid",null,List.of(rol))).token();}
 Map<String,Object> usuario(String rol){var datos=new HashMap<String,Object>();datos.put("nombre",prefijo+"Nueva");datos.put("correo",prefijo+"nueva@example.invalid");datos.put("contrasena","NuevaPrueba!2026");datos.put("rol",rol);datos.put("estado","activo");if(rol.equals("tutor"))datos.put("departamentoId",departamento);if(rol.equals("estudiante"))datos.put("matricula",prefijo+"MAT");return datos;}
 Map<String,Object> catalogo(){return new HashMap<>(Map.of("nombre",prefijo+"Catálogo","clave",prefijo+"CL","estado","activo"));}
 ResultActions enviar(String destino,Object datos)throws Exception{return cliente.perform(post(ruta+destino).header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(datos)));}
 long id(ResultActions respuesta)throws Exception{return json.readTree(respuesta.andReturn().getResponse().getContentAsString()).path("id").asLong();}
 @BeforeEach void preparar(){
  cliente=MockMvcBuilders.webAppContextSetup(contexto).addFilters(filtro).build();prefijo="ADM"+UUID.randomUUID().toString().substring(0,8);
  coordinador=cuenta("Coord","coordinador");alumno=cuenta("Alumno","estudiante");profesor=cuenta("Profesor","tutor");
  departamento=insertar("INSERT INTO departamentos(nombre) VALUES (?)",prefijo+"Departamento");carrera=insertar("INSERT INTO carreras(nombre,clave,departamento_id) VALUES (?,?,?)",prefijo+"Carrera",prefijo+"CAR",departamento);
  periodo=insertar("INSERT INTO periodos_academicos(nombre,clave,fecha_inicio,fecha_fin,estado) VALUES (?,?,'2099-01-01','2099-12-31','activo')",prefijo+"Periodo",prefijo+"PER");
  estudiante=insertar("INSERT INTO estudiantes(usuario_id,matricula) VALUES (?,?)",alumno,prefijo+"AL");tutor=insertar("INSERT INTO tutores(usuario_id,departamento_id) VALUES (?,?)",profesor,departamento);
  insertar("INSERT INTO situaciones_academicas(estudiante_id,periodo_id,carrera_id,semestre) VALUES (?,?,?,3)",estudiante,periodo,carrera);
  insertar("INSERT INTO asignaciones_tutor(estudiante_id,tutor_id,periodo_id,asignado_por,inicio_en,estado) VALUES (?,?,?,?,UTC_TIMESTAMP(),'activa')",estudiante,tutor,periodo,coordinador);
  sesion=insertar("INSERT INTO sesiones(tutor_id,estudiante_id,periodo_id,tema,inicio_en,fin_en,modalidad,ubicacion,creado_por) VALUES (?,?,?,?,'2099-06-01 16:00:00','2099-06-01 17:00:00','presencial','Aula 5',?)",tutor,estudiante,periodo,prefijo+"Tutoría",alumno);
 }
 @Test void soloCoordinacionAccedeALosTresModulos()throws Exception{for(String modulo:List.of("usuarios","catalogos/carreras","tutorias")){cliente.perform(get(ruta+"/"+modulo)).andExpect(status().isUnauthorized());for(String rol:List.of("estudiante","tutor"))cliente.perform(get(ruta+"/"+modulo).header("Authorization",token(rol.equals("tutor")?profesor:alumno,rol))).andExpect(status().isForbidden());}cliente.perform(post(ruta+"/usuarios").header("Authorization",token(alumno,"estudiante")).contentType("application/json").content(json.writeValueAsString(usuario("coordinador")))).andExpect(status().isForbidden());}
 @Test void usuariosSePaginanYFiltranEnServidorSinSecretos()throws Exception{for(int n=0;n<3;n++)cuenta("Busqueda"+n,"estudiante");cliente.perform(get(ruta+"/usuarios").param("busqueda",prefijo+"Busqueda").param("rol","estudiante").param("pagina","2").param("tamano","2").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(3)).andExpect(jsonPath("$.paginas").value(2)).andExpect(jsonPath("$.contenido.length()").value(1)).andExpect(jsonPath("$.contenido[0].password_hash").doesNotExist());}
 @Test void creaEstudianteConRolMatriculaYContrasenaHasheada()throws Exception{long nuevo=id(enviar("/usuarios",usuario("estudiante")).andExpect(status().isCreated()));assertThat(consultas.queryForObject("SELECT COUNT(*) FROM estudiantes WHERE usuario_id=?",Long.class,nuevo)).isEqualTo(1);String hash=consultas.queryForObject("SELECT password_hash FROM usuarios WHERE id=?",String.class,nuevo);assertThat(codificador.matches("NuevaPrueba!2026",hash)).isTrue();assertThat(consultas.queryForObject("SELECT COUNT(*) FROM usuario_roles WHERE usuario_id=?",Long.class,nuevo)).isEqualTo(1);}
 @Test void creaTutorConDepartamentoValido()throws Exception{enviar("/usuarios",usuario("tutor")).andExpect(status().isCreated()).andExpect(jsonPath("$.departamentoId").value(departamento));}
 @Test void rechazaContrasenaDebilYMatriculaVacia()throws Exception{var datos=usuario("estudiante");datos.put("contrasena","debil");datos.put("matricula","");enviar("/usuarios",datos).andExpect(status().isUnprocessableEntity());assertThat(consultas.queryForObject("SELECT COUNT(*) FROM usuarios WHERE correo=?",Long.class,datos.get("correo"))).isZero();}
 @Test void rechazaCorreoDuplicado()throws Exception{var datos=usuario("coordinador");datos.put("correo",prefijo+"Alumno@example.invalid");enviar("/usuarios",datos).andExpect(status().isConflict());}
 @Test void noPermiteQuitarElAccesoPropio()throws Exception{var datos=usuario("coordinador");datos.put("correo",prefijo+"Coord@example.invalid");datos.put("estado","inactivo");cliente.perform(put(ruta+"/usuarios/"+coordinador).header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(datos))).andExpect(status().isConflict());}
 @Test void cambiarRolInvalidaTokensAnteriores()throws Exception{long otro=cuenta("Otro","coordinador");String anterior=token(otro,"coordinador");var datos=usuario("tutor");datos.remove("contrasena");datos.put("correo",prefijo+"Otro@example.invalid");cliente.perform(put(ruta+"/usuarios/"+otro).header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(datos))).andExpect(status().isOk()).andExpect(jsonPath("$.roles[0]").value("tutor"));cliente.perform(get(ruta+"/usuarios").header("Authorization",anterior)).andExpect(status().isUnauthorized());}
 @Test void noCambiaRolDeUsuarioConAsignacionActiva()throws Exception{var datos=usuario("coordinador");datos.remove("contrasena");datos.put("correo",prefijo+"Alumno@example.invalid");cliente.perform(put(ruta+"/usuarios/"+alumno).header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(datos))).andExpect(status().isConflict());}
 @Test void catalogosCreanEditanYDanBajaSinBorrarHistorial()throws Exception{var datos=catalogo();long nuevo=id(enviar("/catalogos/departamentos",datos).andExpect(status().isCreated()));datos.put("nombre",prefijo+"Renombrado");cliente.perform(put(ruta+"/catalogos/departamentos/"+nuevo).header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(datos))).andExpect(status().isOk()).andExpect(jsonPath("$.nombre").value(prefijo+"Renombrado"));cliente.perform(delete(ruta+"/catalogos/departamentos/"+nuevo).header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isOk()).andExpect(jsonPath("$.estado").value("inactivo"));assertThat(consultas.queryForObject("SELECT COUNT(*) FROM departamentos WHERE id=?",Long.class,nuevo)).isEqualTo(1);}
 @Test void carreraRequiereDepartamentoActivo()throws Exception{var datos=catalogo();datos.put("departamentoId",departamento);enviar("/catalogos/carreras",datos).andExpect(status().isCreated());consultas.update("UPDATE departamentos SET activo=0 WHERE id=?",departamento);datos.put("clave",prefijo+"OTRA");enviar("/catalogos/carreras",datos).andExpect(status().isUnprocessableEntity());}
 @Test void periodosRequierenFechasValidas()throws Exception{var datos=catalogo();datos.put("inicio","2031-12-31");datos.put("fin","2031-01-01");enviar("/catalogos/periodos",datos).andExpect(status().isUnprocessableEntity());datos.put("fin","2031-12-31");enviar("/catalogos/periodos",datos).andExpect(status().isCreated()).andExpect(jsonPath("$.inicio").value("2031-12-31"));}
 @Test void noCierraPeriodoConSesionesPendientes()throws Exception{cliente.perform(delete(ruta+"/catalogos/periodos/"+periodo).header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isConflict());}
 @Test void catalogosFiltranYPaginanSinAceptarNombresDeTabla()throws Exception{cliente.perform(get(ruta+"/catalogos/carreras").param("busqueda",prefijo).param("tamano","1").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(1));cliente.perform(get(ruta+"/catalogos/usuarios").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isNotFound());}
 @Test void tutoriasFiltranPorTemaFechaYModalidad()throws Exception{cliente.perform(get(ruta+"/tutorias").param("busqueda",prefijo).param("fecha","2099-06-01").param("modalidad","presencial").param("estado","solicitada").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(1)).andExpect(jsonPath("$.contenido[0].id").value(sesion));cliente.perform(get(ruta+"/tutorias").param("busqueda",prefijo).param("modalidad","virtual").header("Authorization",token(coordinador,"coordinador"))).andExpect(jsonPath("$.total").value(0));}
 @Test void coordinacionConfirmaSesionYRegistraSuIdentidad()throws Exception{cliente.perform(patch(ruta+"/tutorias/"+sesion+"/confirmar").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isOk()).andExpect(jsonPath("$.estado").value("confirmada"));assertThat(consultas.queryForObject("SELECT actor_id FROM sesion_cambios WHERE sesion_id=? ORDER BY id DESC LIMIT 1",Long.class,sesion)).isEqualTo(coordinador);cliente.perform(patch(ruta+"/tutorias/"+sesion+"/cancelar").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isOk()).andExpect(jsonPath("$.estado").value("cancelada"));}
 @Test void noConfirmaSinAsignacionNiDuplicaLaTransicion()throws Exception{consultas.update("UPDATE asignaciones_tutor SET estado='cancelada',fin_en=UTC_TIMESTAMP() WHERE estudiante_id=?",estudiante);cliente.perform(patch(ruta+"/tutorias/"+sesion+"/confirmar").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isConflict());cliente.perform(patch(ruta+"/tutorias/"+sesion+"/rechazar").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isOk());cliente.perform(patch(ruta+"/tutorias/"+sesion+"/rechazar").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isConflict());}
 @Test void rechazaPaginasYFiltrosInvalidos()throws Exception{cliente.perform(get(ruta+"/usuarios").param("pagina","0").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isUnprocessableEntity());cliente.perform(get(ruta+"/tutorias").param("modalidad","cualquiera").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isUnprocessableEntity());cliente.perform(get(ruta+"/catalogos/carreras").param("estado","cerrado").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isUnprocessableEntity());}

 Map<String,Object> expedienteDatos(){return new HashMap<>(Map.of("matricula",prefijo+"AL","periodoId",periodo,"carreraId",carrera,"semestre",8,"inscripcion","activo","promedio",8.75,"riesgo","bajo","condicion","Seguimiento"));}
 Map<String,Object> reporteDatos(){return new HashMap<>(Map.of("estudianteId",estudiante,"tutorId",tutor,"periodoId",periodo,"motivoId",insertar("INSERT INTO motivos_reporte(codigo,nombre) VALUES (?,?)",prefijo+"MOT",prefijo+"Motivo"),"fecha",java.time.LocalDate.now().toString(),"contenido","Contenido del reporte","estado","pendiente"));}
 Map<String,Object> tutoriaDatos(){return new HashMap<>(Map.of("estudianteId",estudiante,"tutorId",tutor,"periodoId",periodo,"tema","Seguimiento","inicioEn","2099-07-01T16:00:00","finEn","2099-07-01T17:00:00","modalidad","presencial","lugar","Aula 10"));}
 @Test void coordinacionActualizaExpedienteYGuardaMedicionConAutor()throws Exception{consultas.update("INSERT INTO mediciones_academicas(situacion_id,medido_en,materias_reprobadas,registrado_por) SELECT id,'2000-01-01',2,? FROM situaciones_academicas WHERE estudiante_id=? AND periodo_id=?",coordinador,estudiante,periodo);cliente.perform(put(ruta+"/estudiantes/"+estudiante+"/expediente").header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(expedienteDatos()))).andExpect(status().isOk()).andExpect(jsonPath("$.periodos[0].semestre").value(8)).andExpect(jsonPath("$.periodos[0].promedio").value(8.75));assertThat(consultas.queryForObject("SELECT registrado_por FROM mediciones_academicas WHERE situacion_id=(SELECT id FROM situaciones_academicas WHERE estudiante_id=? AND periodo_id=?) ORDER BY id DESC LIMIT 1",Long.class,estudiante,periodo)).isEqualTo(coordinador);assertThat(consultas.queryForObject("SELECT materias_reprobadas FROM mediciones_academicas WHERE situacion_id=(SELECT id FROM situaciones_academicas WHERE estudiante_id=? AND periodo_id=?) ORDER BY medido_en DESC,id DESC LIMIT 1",Integer.class,estudiante,periodo)).isEqualTo(2);}
 @Test void expedienteRechazaSemestre13YBajaConSesionPendiente()throws Exception{var datos=expedienteDatos();datos.put("semestre",13);cliente.perform(put(ruta+"/estudiantes/"+estudiante+"/expediente").header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(datos))).andExpect(status().isUnprocessableEntity());datos.put("semestre",12);datos.put("inscripcion","baja");cliente.perform(put(ruta+"/estudiantes/"+estudiante+"/expediente").header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(datos))).andExpect(status().isConflict());}
 @Test void bajaAcademicaFinalizaAsignacionSinBorrarHistorial()throws Exception{consultas.update("UPDATE sesiones SET estado='cancelada' WHERE id=?",sesion);var datos=expedienteDatos();datos.put("inscripcion","baja");cliente.perform(put(ruta+"/estudiantes/"+estudiante+"/expediente").header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(datos))).andExpect(status().isOk());assertThat(consultas.queryForObject("SELECT estado FROM asignaciones_tutor WHERE estudiante_id=? AND periodo_id=?",String.class,estudiante,periodo)).isEqualTo("finalizada");}
 @Test void gestionCompletaDeReportesRespetaAutorDeCierre()throws Exception{var datos=reporteDatos();long id=id(enviar("/reportes",datos).andExpect(status().isCreated()));datos.put("estado","completado");datos.put("contenido","Revisado por coordinación");cliente.perform(put(ruta+"/reportes/"+id).header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(datos))).andExpect(status().isOk()).andExpect(jsonPath("$.estado").value("completado"));assertThat(consultas.queryForObject("SELECT completado_por FROM reportes WHERE id=?",Long.class,id)).isEqualTo(coordinador);datos.put("estado","pendiente");cliente.perform(put(ruta+"/reportes/"+id).header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(datos))).andExpect(status().isOk()).andExpect(jsonPath("$.completadoEn").isEmpty());cliente.perform(delete(ruta+"/reportes/"+id).header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isNoContent());cliente.perform(get(ruta+"/reportes/"+id).header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isNotFound());}
 @Test void reporteRechazaFechaFuturaYSinAsignacion()throws Exception{var datos=reporteDatos();datos.put("fecha",java.time.LocalDate.now().plusDays(1).toString());enviar("/reportes",datos).andExpect(status().isUnprocessableEntity());datos.put("fecha",java.time.LocalDate.now().toString());consultas.update("UPDATE asignaciones_tutor SET estado='cancelada',fin_en=UTC_TIMESTAMP() WHERE estudiante_id=?",estudiante);enviar("/reportes",datos).andExpect(status().isConflict());}
 @Test void contextoSeBuscaYPaginaEnServidor()throws Exception{cliente.perform(get(ruta+"/contextos").param("busqueda",prefijo).param("tamano","1").header("Authorization",token(coordinador,"coordinador"))).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(1)).andExpect(jsonPath("$.contenido[0].estudianteId").value(estudiante));}
 @Test void programaYReprogramaTutoriaConHistorialSinCruzarHorarios()throws Exception{var datos=tutoriaDatos();long id=id(enviar("/tutorias",datos).andExpect(status().isCreated()).andExpect(jsonPath("$.estado").value("confirmada")));enviar("/tutorias",datos).andExpect(status().isConflict());datos.put("inicioEn","2099-07-02T16:00:00");datos.put("finEn","2099-07-02T17:00:00");cliente.perform(put(ruta+"/tutorias/"+id).header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content(json.writeValueAsString(datos))).andExpect(status().isOk());assertThat(consultas.queryForObject("SELECT COUNT(*) FROM sesion_cambios WHERE sesion_id=? AND actor_id=?",Long.class,id,coordinador)).isEqualTo(2);}
 @Test void registraTutoriaPasadaYCierraConfirmadaComoCoordinacion()throws Exception{var datos=tutoriaDatos();datos.put("inicioEn","2020-01-01T16:00:00");datos.put("finEn","2020-01-01T17:00:00");enviar("/tutorias",datos).andExpect(status().isCreated()).andExpect(jsonPath("$.estado").value("completada"));consultas.update("UPDATE sesiones SET estado='confirmada',inicio_en='2020-02-01 16:00:00',fin_en='2020-02-01 17:00:00' WHERE id=?",sesion);cliente.perform(patch(ruta+"/tutorias/"+sesion+"/cerrar").header("Authorization",token(coordinador,"coordinador")).contentType("application/json").content("{\"estado\":\"completada\",\"inicioRealEn\":\"2020-02-01T16:00:00\",\"finRealEn\":\"2020-02-01T17:00:00\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.estado").value("completada"));assertThat(consultas.queryForObject("SELECT actor_id FROM sesion_cambios WHERE sesion_id=? AND tipo='cierre'",Long.class,sesion)).isEqualTo(coordinador);}
 @Test void nuevasOperacionesRechazanAccesoDeTutorYEstudiante()throws Exception{var reporte=reporteDatos();for(String rol:List.of("tutor","estudiante")){String token=token(rol.equals("tutor")?profesor:alumno,rol);cliente.perform(get(ruta+"/estudiantes/"+estudiante+"/expediente").header("Authorization",token)).andExpect(status().isForbidden());cliente.perform(post(ruta+"/reportes").header("Authorization",token).contentType("application/json").content(json.writeValueAsString(reporte))).andExpect(status().isForbidden());cliente.perform(post(ruta+"/tutorias").header("Authorization",token).contentType("application/json").content(json.writeValueAsString(tutoriaDatos()))).andExpect(status().isForbidden());}}
}
